def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2 and any(grid[rr][cc] == 3 for rr in [r] for cc in [c])]
    for r,c in seeds:
        for rr in range(max(0,r-1),min(h,r+2)):
            for cc in range(max(0,c-1),min(w,c+2)):
                if grid[rr][cc] != 2: out[rr][cc] = 1
    return out
